228	async function handleStreamingError(resp: Response): Promise<ProviderResponse> {
229	  try {
230	    const errData = (await resp.json()) as QuiverAiErrorResponse;
231	    return { error: formatError(errData) };
232	  } catch {
233	    return { error: `QuiverAI API error: HTTP ${resp.status}` };
234	  }
235	}
