24	function extractBase64(value: string): { buffer: Buffer; mimeType: string } | null {
25	  const match = value.match(/^data:([^;]+);base64,(.+)$/);
26	  if (!match) {
27	    return null;
28	  }
29	  const mimeType = match[1];
30	  try {
31	    return { buffer: Buffer.from(match[2], 'base64'), mimeType };
32	  } catch (error) {
33	    logger.warn('[BlobExtractor] Failed to parse base64 data URL', { error });
34	    return null;
35	  }
36	}
