94	function parseBinary(
95	  base64OrDataUrl: string,
96	  defaultMimeType: string,
97	): { buffer: Buffer; mimeType: string } | null {
98	  if (isDataUrl(base64OrDataUrl)) {
99	    const parsed = extractBase64(base64OrDataUrl);
100	    if (!parsed) {
101	      return null;
102	    }
103	    return parsed;
104	  }
105	
106	  try {
107	    return { buffer: Buffer.from(base64OrDataUrl, 'base64'), mimeType: defaultMimeType };
108	  } catch (error) {
109	    logger.warn('[BlobExtractor] Failed to parse base64 data', { error });
110	    return null;
111	  }
112	}
