19	let defaultProvider: BlobStorageProvider | null = null;
20	
21	function createDefaultProvider(): BlobStorageProvider {
22	  // OSS: filesystem-only media storage. Cloud/on-prem can override by calling setBlobStorageProvider().
23	  return new FilesystemBlobStorageProvider();
24	}
25	
26	export function getBlobStorageProvider(): BlobStorageProvider {
27	  if (!defaultProvider) {
28	    defaultProvider = createDefaultProvider();
29	    logger.debug('[BlobStorage] Initialized provider', { provider: defaultProvider.providerId });
30	  }
31	  return defaultProvider;
32	}
33	
34	export function setBlobStorageProvider(provider: BlobStorageProvider): void {
35	  defaultProvider = provider;
36	  logger.debug('[BlobStorage] Provider set', { provider: provider.providerId });
37	}
38	
39	export function resetBlobStorageProvider(): void {
40	  defaultProvider = null;
41	}
