32	export class FilesystemBlobStorageProvider implements BlobStorageProvider {
33	  readonly providerId = 'filesystem';
34	  private readonly basePath: string;
35	
36	  constructor(config?: FilesystemProviderConfig) {
37	    const defaultBase = path.join(getConfigDirectoryPath(true), DEFAULT_FILESYSTEM_SUBDIR);
38	    this.basePath = path.resolve(config?.basePath || defaultBase);
39	    this.ensureDirectory();
40	  }
41	
42	  private ensureDirectory(): void {
43	    if (!fs.existsSync(this.basePath)) {
44	      fs.mkdirSync(this.basePath, { recursive: true });
45	      logger.debug('[BlobFS] Created blob directory', { basePath: this.basePath });
46	    }
47	  }
48	
49	  private assertValidHash(hash: string): void {
50	    if (!BLOB_HASH_REGEX.test(hash)) {
51	      throw new Error(`[BlobFS] Invalid blob hash: "${hash}"`);
52	    }
53	  }
54	
55	  private resolvePathInBase(unsafePath: string): string {
56	    const targetPath = path.isAbsolute(unsafePath)
57	      ? path.resolve(unsafePath)
58	      : path.resolve(this.basePath, unsafePath);
59	
60	    const safeBase = path.resolve(this.basePath) + path.sep;
61	    if (!targetPath.startsWith(safeBase)) {
62	      throw new Error('[BlobFS] Path traversal attempt detected');
63	    }
64	
65	    return targetPath;
66	  }
67	
68	  private hashToPath(hash: string): string {
69	    this.assertValidHash(hash);
70	
71	    const dirRelative = path.join(hash.slice(0, 2), hash.slice(2, 4));
72	    const fileRelative = path.join(dirRelative, hash);
73	    return this.resolvePathInBase(fileRelative);
74	  }
75	
76	  private async ensureHashDir(hash: string): Promise<void> {
77	    this.assertValidHash(hash);
78	
79	    const dirRelative = path.join(hash.slice(0, 2), hash.slice(2, 4));
80	    const dirPath = this.resolvePathInBase(dirRelative);
81	    await fsPromises.mkdir(dirPath, { recursive: true });
82	  }
83	
84	  private metadataPath(filePath: string): string {
85	    return `${filePath}.meta.json`;
86	  }
87	
88	  async store(data: Buffer, mimeType: string): Promise<BlobStoreResult> {
89	    const hash = computeHash(data);
90	    await this.ensureHashDir(hash);
91	    const filePath = this.hashToPath(hash);
92	
93	    // Check if file already exists (deduplication)
94	    try {
95	      await fsPromises.access(filePath);
96	      const meta = await this.readMetadata(filePath);
97	      const ref = this.buildRef(
98	        hash,
99	        meta?.mimeType ?? mimeType,
100	        meta?.sizeBytes ?? data.length,
101	        meta?.provider ?? this.providerId,
102	      );
103	      return { ref, deduplicated: true };
104	    } catch {
105	      // File doesn't exist, proceed with storing
106	    }
107	
108	    await fsPromises.writeFile(filePath, data);
109	
110	    const metadata: BlobMetadata = {
111	      mimeType,
112	      sizeBytes: data.length,
113	      createdAt: new Date().toISOString(),
114	      provider: this.providerId,
115	      key: filePath,
116	    };
117	    await fsPromises.writeFile(this.metadataPath(filePath), JSON.stringify(metadata, null, 2));
118	
119	    return {
120	      ref: this.buildRef(hash, mimeType, data.length, this.providerId),
121	      deduplicated: false,
122	    };
123	  }
124	
125	  async getByHash(hash: string): Promise<StoredBlob> {
126	    const filePath = this.hashToPath(hash);
127	
128	    let data: Buffer;
129	    try {
130	      data = await fsPromises.readFile(filePath);
131	    } catch (error) {
132	      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
133	        throw new Error(`Blob not found: ${hash}`);
134	      }
135	      throw error;
136	    }
137	
138	    const metadata =
139	      (await this.readMetadata(filePath)) ||
140	      ({
141	        mimeType: 'application/octet-stream',
142	        sizeBytes: data.length,
143	        createdAt: new Date().toISOString(),
144	        provider: this.providerId,
145	        key: filePath,
146	      } satisfies BlobMetadata);
147	    return { data, metadata };
148	  }
149	
150	  async exists(hash: string): Promise<boolean> {
151	    try {
152	      const filePath = this.hashToPath(hash);
153	      await fsPromises.access(filePath);
154	      return true;
155	    } catch {
156	      return false;
157	    }
158	  }
159	
160	  async deleteByHash(hash: string): Promise<void> {
161	    try {
162	      const filePath = this.hashToPath(hash);
163	      const metaPath = this.metadataPath(filePath);
164	
165	      // Delete files (ignore ENOENT errors)
166	      try {
167	        await fsPromises.unlink(filePath);
168	      } catch (error) {
169	        if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
170	          throw error;
171	        }
172	      }
173	      try {
174	        await fsPromises.unlink(metaPath);
175	      } catch (error) {
176	        if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
177	          throw error;
178	        }
179	      }
180	    } catch {
181	      // Ignore invalid hashes/path traversal attempts
182	    }
183	  }
184	
185	  async getUrl(_hash: string, _expiresInSeconds?: number): Promise<string | null> {
186	    // Local filesystem is proxied; return null to signal proxy route.
187	    return null;
188	  }
189	
190	  private buildRef(hash: string, mimeType: string, sizeBytes: number, provider: string): BlobRef {
191	    return {
192	      uri: buildUri(hash),
193	      hash,
194	      mimeType,
195	      sizeBytes,
196	      provider,
197	    };
198	  }
199	
200	  private async readMetadata(filePath: string): Promise<BlobMetadata | null> {
201	    const safeFilePath = this.resolvePathInBase(filePath);
202	    const metaPath = this.metadataPath(safeFilePath);
203	    try {
204	      const raw = await fsPromises.readFile(metaPath, 'utf8');
205	      return JSON.parse(raw) as BlobMetadata;
206	    } catch (error) {
207	      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
208	        return null;
209	      }
210	      logger.warn('[BlobFS] Failed to read metadata', { error });
211	      return null;
212	    }
213	  }
214	}
