 * deduplicating against `existingBlobUris`. Returns the computed blob URI (derived
 * from the SHA-256 of the UTF-8 SVG bytes) when a new blob was stored, or null when
 * storage is disabled, the SVG is already tracked, or the store failed.
 */
async function maybeStoreSvgPreview(
  svgText: string,
  existingBlobUris: string[],
  blobContext: BlobContext,
  context: BlobContext | undefined,
): Promise<string | null> {
  const buffer = Buffer.from(svgText, 'utf-8');
  const uri = `${BLOB_SCHEME}${sha256(buffer)}`;

